sources.inspect_runtime.py:
from pathlib import Path
import json,datetime,httpx,collections,re,os
R=Path(__file__).resolve().parent
sequence=json.loads((R/'sequence_status.json').read_text())
out={'checked_at':datetime.datetime.now().astimezone().isoformat(),'sequence':sequence,'webshop':{}}
for port in range(8321,8325):
    try:
        m=httpx.get(f'http://127.0.0.1:{port}/meta',timeout=5).json()
        log=(R/f'webshop-{port}.log').read_text(errors='replace')
        out['webshop'][str(port)]={'active':m['active'],'stats':m['transport_stats'],
            'http_statuses':dict(collections.Counter(re.findall(r'POST /(?:step|reset|release) HTTP/1.1" (\d+)',log))),
            'disconnects':log.count('client disconnected'),'tracebacks':log.count('Traceback')}
    except Exception as e:out['webshop'][str(port)]={'error':type(e).__name__}
run=Path(sequence.get('run',str(R/'code/runs/pass5_compact3072_all_skill_s42')))
out['rollout_rows']={p.name:len(list(p.glob('*.json'))) for p in (run/'rollouts').glob('*') if p.is_dir()}
logpath=Path(sequence.get('owner_state','/tmp/p5compact3072-all24r3'))/'command.log'
if logpath.exists():
    text=logpath.read_text(errors='replace')
    out['error_mentions']={k:text.count(k) for k in ['webshop service unreachable','webshop HTTP 409','student episode infra error','OutOfMemoryError','ReplayBuffer:']}
    out['training_tail']=text.splitlines()[-4:]
    lines=[s for s in text.splitlines() if 'timing_s/step' in s]
    out['completed_steps']=[int(m.group(1)) for s in lines if (m:=re.search(r'step:\s*(\d+)',s))]
    out['timing_rows']=[{k:float(v) for k,v in re.findall(r'(timing_s/[a-z_]+):([0-9.eE+\-]+)',s)} for s in lines]
actual=[]
for p in run.rglob('*.jsonl'):
    if 'tape' not in str(p):continue
    for line in p.open(errors='replace'):
        try:d=json.loads(line)
        except json.JSONDecodeError:continue
        if d.get('role')=='researcher' and d.get('usage'):
            n=d['usage'].get('prompt_tokens',0)
            if n:actual.append(n)
out['researcher_inputs']={'calls':len(actual),'mean':sum(actual)/len(actual) if actual else None,'max':max(actual) if actual else None,'above_3072':sum(n>3072 for n in actual)}
(R/'runtime_snapshot.json').write_text(json.dumps(out,indent=2))
print(json.dumps(out,indent=2))

sources.audit_run.py:
"""Fail-closed audit of complete, single-launch training runs and bare validation."""
from pathlib import Path
import json,collections,hashlib,sys
import pyarrow.parquet as pq
R=Path(__file__).resolve().parent
sys.path.insert(0,str(R/'code/src'))
from trace_opd.common.config import load_config

def require(ok,message):
 if not ok:raise ValueError(message)

def read_evaluation(run,launch,step,ids,n,temperature):
 rows=[json.loads(p.read_text()) for p in (run/'rollouts'/f'step_{step:05d}_val').glob('*.json')]
 require(len(rows)==len(ids)*n,f'eval {step}: incomplete or duplicate rows {len(rows)}')
 seen=set(); samples=set();out={t:[] for t in ids}
 for d in rows:
  t=d['task_id'];sid=d['session_id'];key=(t,sid)
  require(t in ids and type(sid) is int and 0<=sid<n and key not in seen,f'eval identity {key}')
  require(d.get('sample_id') and d['sample_id'] not in samples,'duplicate sample identity')
  seen.add(key);samples.add(d['sample_id'])
  require(d['validate'] is True and d['split']=='dev' and d['global_step']==step,'wrong eval split/step')
  require(d['evaluation_id']==f'{launch}:val:{step}','wrong launch evaluation')
  require(d['evaluation_n']==n and d['evaluation_temperature']==temperature and d['evaluation_bare'] is True,'wrong eval sampling')
  require(d['policy_version']=={'min_global_steps':step,'max_global_steps':step},'stale or mixed eval weights')
  require(not d['steering'] and not d['research'],'guided validation')
  require(d['outcome']!='ENV_ERROR' and type(d['won']) is bool,'invalid outcome')
  require(bool(d['won'])==bool(d['trajectory']['won']) and d['score']==d['trajectory']['score'],'inconsistent result')
  out[t].append(int(d['won']))
 return out

def audit(config,state,steps=None):
 cfg=load_config(config);run=R/'code'/cfg.run.runs_root/cfg.run.name
 owner=json.loads(Path(state,'status.json').read_text());require(owner['result_status']=='COMPLETE' and owner['returncode']==0 and owner['ended_at'],'owner not complete')
 manifests=list(run.glob('launch_manifest_*.json'));require(len(manifests)==1,'run must have exactly one launch')
 m=json.loads(manifests[0].read_text()); require(not m['overrides'],'unreviewed launch overrides')
 n=cfg.train.total_training_steps
 require(int((run/'checkpoints/latest_checkpointed_iteration.txt').read_text())==n,'final checkpoint missing')
 require(len(list((run/f'checkpoints/global_step_{n}/actor').glob('model_world_size_*_rank_*.pt')))==cfg.train.n_gpus,'checkpoint ranks missing')
 ids={x['extra_info']['task_id'] for path in cfg.train.val_files for x in pq.read_table(path).to_pylist()}
 steps=steps or [0]+list(range(cfg.train.test_freq,n+1,cfg.train.test_freq))
 ev={step:read_evaluation(run,m['launch_id'],step,ids,cfg.eval.n,cfg.eval.temperature) for step in steps}
 train_ids={x['extra_info']['task_id'] for x in pq.read_table(cfg.train.train_file).to_pylist()}
 gate=json.loads(Path(cfg.steering.task_gate_path).read_text())['tasks'] if cfg.steering.task_gate_path else {}
 research={};steered=0;skipped=0;rows_count=0
 for step in range(1,n+1):
  rows=[json.loads(p.read_text()) for p in (run/'rollouts'/f'step_{step:05d}').glob('*.json')]
  require(len(rows)==cfg.train.train_batch_size*cfg.train.rollout_n,f'train step {step}: wrong row count')
  seen=set();groups=collections.defaultdict(set)
  for d in rows:
   tid=d['task_id']; sid=d['session_id'];key=(tid,sid);require(tid in train_ids and key not in seen,'train identity duplicate/unknown');seen.add(key);groups[tid].add(sid)
   require(d['validate'] is False and d['split']=='train' and d['global_step']==step and d['outcome']!='ENV_ERROR','invalid train row')
   st=d['steering'];rs=d['research'];rows_count+=1
   eligible=not gate or gate[tid]['skill_eligible']
   if cfg.steering.enabled:
    require(st.get('steer_arm')==int(eligible and sid<cfg.train.rollout_n*cfg.steering.steered_fraction),'incorrect Skill arm')
    if gate:require(st.get('task_skill_eligible')==int(eligible),'incorrect task eligibility')
    steered+=st['steer_arm']
    if eligible:
     research_ok=rs.get('research_error')==0 and rs.get('research_doc_missing')==0 and rs.get('research_doc_words',0)>0
     if n<=2:require(research_ok,'smoke research failed or guidance absent')
     if research_ok:require(rs.get('research_policy_version')==step-1,'stale research policy')
     if rs.get('research_archive'):
      archive=run/rs['research_archive'];require(archive.is_dir() and (archive/'meta.json').is_file(),'missing research archive')
      if research_ok:require((archive/'doc.md').is_file(),'missing Skill document')
     old=research.setdefault((step,tid),rs);require(old==rs,'shared research metadata inconsistent')
    else:
     skipped+=1;require(rs.get('research_experiments')==0 and rs.get('research_episodes')==0 and not rs.get('research_archive'),'high task used researcher')
   else:require(not st and not rs,'GRPO unexpectedly guided')
  require(len(groups)==cfg.train.train_batch_size and all(v==set(range(cfg.train.rollout_n)) for v in groups.values()),'incomplete train groups')
 out={'run':str(run),'launch_id':m['launch_id'],'updates':n,'validation':{str(k):{'tasks':len(v),'attempts':sum(map(len,v.values())),'success_rate':sum(map(sum,v.values()))/sum(map(len,v.values()))} for k,v in ev.items()},'train_rows':rows_count,'steered_rows':steered,'intentional_skipped_rows':skipped,'research_sessions':len(research),'research_experiments':sum(v['research_experiments'] for v in research.values()),'research_episodes':sum(v['research_episodes'] for v in research.values()),'passed':True}
 (run/'completion_audit.json').write_text(json.dumps(out,indent=2));return out

if __name__=='__main__':print(json.dumps(audit(Path(sys.argv[1]),Path(sys.argv[2])),indent=2))
